// insertion into a dictionary. It returns 1 and writes the value when present.
// A return of 0 represents the KeyError Python raises when the key is absent.
// Counts and lengths must be nonnegative, and each key occupies one key_stride
// block large enough for its stated length.
int py_string_dict_lookup(const long *keys, const long *key_lengths,
                          const long *values, long count, long key_stride,
                          const long *query, long query_len, long *out_value)
{
