// synth: library theory (phase 0)
// doc: A bounded Python list iterator visits indices from zero upward. It observes
// doc: element and length mutations until exhausted; once exhausted, next() always
// doc: raises StopIteration.
typedef struct {
    // doc: The currently visible list elements.
    const long *elements;
    // doc: The currently visible list length, between zero and NFV_LEN_MAX.
    const int *length;
    // doc: The index that Python next() will inspect next.
    int next_index;
    // doc: Nonzero after the iterator has raised StopIteration.
    int exhausted;
} nfv_py_long_list_iter;

// doc: Creating iter(list) starts before index zero and raises no exception.
nfv_py_long_list_iter nfv_py_long_list_iter_init(
    const long *elements, const int *length)
{
    // doc: The newly created iterator state.
    nfv_py_long_list_iter result;
    result.elements = elements;
    result.length = length;
    result.next_index = 0;
    result.exhausted = 0;
    return result;
}

// doc: Python next() returns the current indexed element and advances the iterator.
// doc: This function returns 1 and stores that element in value. At or after
// doc: exhaustion it returns 0, representing StopIteration, and remains exhausted.
int nfv_py_long_list_iter_next(
    nfv_py_long_list_iter *iterator, long *value)
{
    if (iterator->exhausted)
        return 0;
    if (iterator->next_index >= *iterator->length) {
        iterator->exhausted = 1;
        return 0;
    }
    *value = iterator->elements[iterator->next_index];
    iterator->next_index++;
    return 1;
}

// doc: A Python dictionary item is a two-tuple whose index 0 is the key and whose
// doc: index 1 is the value; those two indices cannot raise IndexError.
typedef struct {
    // doc: The integer dictionary key.
    long key;
    // doc: The integer dictionary value.
    long value;
} nfv_py_long_dict_item;

// doc: A bounded dictionary with integer keys and values retains Python insertion
// doc: order. Updating an existing key does not change its position.
typedef struct {
    // doc: Items in insertion order; only indices below length are present.
    nfv_py_long_dict_item items[NFV_LEN_MAX];
    // doc: The number of present keys, between zero and NFV_LEN_MAX.
    int length;
} nfv_py_long_dict;

// doc: An empty Python dictionary contains no keys and constructing it raises no
// doc: type-driven exception.
nfv_py_long_dict nfv_py_long_dict_empty(void)
{
    // doc: The empty dictionary representation.
    nfv_py_long_dict result;
    result.length = 0;
    return result;
}

// doc: dict.get(key, default) returns the value for an equal key, or default when
// doc: no such key exists. Integer keys are hashable, so this specialization raises
// doc: neither TypeError nor user-defined hashing or equality exceptions.
long nfv_py_long_dict_get(
    const nfv_py_long_dict *dictionary, long key, long default_value)
{
    // doc: The insertion-order position currently being examined.
    int index;
    index = 0;
    while (index < dictionary->length) {
        if (dictionary->items[index].key == key)
            return dictionary->items[index].value;
        index++;
    }
    return default_value;
}

// doc: d[key] = value replaces an equal key's value without changing insertion
// doc: order, or appends a new key at the end. Integer keys cannot raise TypeError.
// doc: Python can raise MemoryError on allocation failure; the bounded model instead
// doc: admits new-key assignments only while its fixed representation has capacity.
void nfv_py_long_dict_set(
    nfv_py_long_dict *dictionary, long key, long value)
{
    // doc: The insertion-order position currently being examined.
    int index;
    index = 0;
    while (index < dictionary->length) {
        if (dictionary->items[index].key == key) {
            dictionary->items[index].value = value;
            return;
        }
        index++;
    }
    __CPROVER_assume(dictionary->length < NFV_LEN_MAX);
    dictionary->items[dictionary->length].key = key;
    dictionary->items[dictionary->length].value = value;
    dictionary->length++;
}

// doc: dict.items() returns a dynamic view of key-value pairs in insertion order;
// doc: it does not copy the dictionary. Integer items require no conversion and
// doc: creating the view raises no type-driven exception.
typedef struct {
