void py_str_reverse(const long *source, long length, long *destination)
{
    // doc: This is a zero-based string position.
    long i;

    if (source == destination) {
        for (i = 0; i < length / 2; ++i) {
            // doc: This temporarily holds one character during an in-place reversal.
            long temporary = destination[i];
            destination[i] = destination[length - 1 - i];
            destination[length - 1 - i] = temporary;
        }
    } else {
        for (i = 0; i < length; ++i)
            destination[i] = source[length - 1 - i];
    }
}

