// doc: element and returns the number equal to it. For integer elements,
// doc: equality is exact and this operation raises no exception.
long py_list_long_count(const long items[], long length, long value) {
    // doc: The number of equal elements encountered so far.
    long count = 0;
    // doc: The index of the element currently being compared.
    long index = 0;

    while (index < length) {
