// synth: library theory (phase 0)
// doc: Python integer modulo raises ZeroDivisionError when the divisor is zero.
// Otherwise it returns the unique remainder having the divisor's sign and
// satisfying a == (a // b) * b + remainder.
int py_int_mod(long a, long b, long *out) {
    // doc: This stores the intermediate C remainder.
    long r;
    if (b == 0)
        return 0;
    if (b == -1) {
        *out = 0;
        return 1;
    }
    r = a % b;
    if (r != 0 && ((r < 0) != (b < 0)))
        r += b;
    *out = r;
    return 1;
}

// doc: Python string indexing accepts indices from -length through length-1;
// negative indices count from the end. Other indices raise IndexError.
// String iteration yields one-character strings in increasing index order.
int py_string_get(const long *data, long length, long index, long *out) {
    if (index < 0)
        index += length;
    if (index < 0 || index >= length)
        return 0;
    *out = data[index];
    return 1;
}

// doc: Assigning an existing dictionary key replaces its value without changing
// insertion order. Assigning a new key appends it in insertion order. Python may
// raise MemoryError while growing a dictionary; returning zero here reports that
// the bounded C representation has no free slot.
int py_dict_set(long *keys, long *values, long *length, long capacity,
                long key, long value) {
    // doc: This is an index into the insertion-ordered dictionary representation.
    long i;
    for (i = 0; i < *length; ++i) {
        if (keys[i] == key) {
            values[i] = value;
            return 1;
        }
    }
    if (*length >= capacity)
        return 0;
    keys[*length] = key;
    values[*length] = value;
    ++*length;
    return 1;
}

// doc: Python dictionary membership returns true exactly when an equal key is
// present. For the represented character-code keys, equality is numeric equality.
int py_dict_contains(const long *keys, long length, long key) {
    // doc: This is an index into the insertion-ordered dictionary representation.
    long i;
    for (i = 0; i < length; ++i)
        if (keys[i] == key)
            return 1;
    return 0;
}

// doc: Python dictionary subscription returns the value associated with an equal
// key and raises KeyError if no such key exists. A zero return encodes KeyError.
