// synth: library theory (phase 0)
// doc: A Python string is an ordered sequence of Unicode characters. This
// bounded representation stores character code points and an explicit length.
typedef struct {
    // doc: Character code points in iteration and indexing order.
    long data[sizeof(long) * 3 + 3];
    // doc: The number of characters currently stored.
    long length;
} py_string;

// doc: Models the outcome of converting a one-character string with int().
// ok is false when Python raises ValueError; otherwise value is the converted
// integer. A non-string argument would instead raise TypeError.
typedef struct {
    // doc: True exactly when conversion succeeds without an exception.
    int ok;
    // doc: The converted integer when ok is true.
    long value;
} py_int_result;

// doc: Models indexing an ordered Python sequence. ok is false when the index
// is outside [-length, length-1], corresponding to IndexError. Negative indices
// count backward from the end. A non-integer index would raise TypeError.
typedef struct {
    // doc: True exactly when the index denotes an element.
    int ok;
    // doc: The selected element when ok is true.
    long value;
} py_index_result;

// doc: Represents an iterator produced by map(int, string). map is lazy: each
// request obtains one source character and then applies int() to it.
typedef struct {
    // doc: The source string, which must remain valid while iterating.
    const py_string *source;
    // doc: The zero-based position of the next source character.
    long position;
} py_int_char_map;

// doc: Represents enumerate(sequence) with its default start of zero.
// Enumeration preserves the underlying sequence's iteration order.
typedef struct {
    // doc: The elements of the fixed, unmodified sequence.
    const long *items;
    // doc: The number of sequence elements.
    long length;
    // doc: The position of the next element.
    long position;
} py_enumerate_long;

// doc: Represents a dictionary whose integer keys map to pairs of integers.
// Integer keys compare by numeric equality. Iteration follows first-insertion
// order; replacing a key's value does not change that order.
typedef struct {
    // doc: Keys in first-insertion order.
    long *keys;
    // doc: First components of the corresponding pair values.
    long *value0;
    // doc: Second components of the corresponding pair values.
    long *value1;
    // doc: The number of distinct keys.
    long length;
    // doc: Allocated capacity, which must cover every distinct inserted key.
    long capacity;
} py_long_pair_dict;

// doc: abs(x) for a Python integer returns x when x is nonnegative and -x
// otherwise, with no overflow because Python integers have arbitrary precision.
// This representation requires that the mathematical result fit in long.
long py_abs_long(long x)
{
    return x < 0 ? -x : x;
}

// doc: str(x) for a Python integer returns its base-ten representation, using
// ASCII digits with no leading zeroes except for zero itself and a leading '-'
// exactly when x is negative. Integer conversion to string raises no ordinary
// value-dependent exception.
py_string py_str_long(long x)
{
    // doc: The resulting Python string representation.
    py_string result;
    // doc: The nonnegative magnitude represented as unsigned arithmetic.
    unsigned long magnitude;
    // doc: A position used while reversing generated decimal digits.
    long left;
    // doc: A position used while reversing generated decimal digits.
    long right;

    result.length = 0;
    if (x < 0) {
        magnitude = (unsigned long)(-(x + 1));
        magnitude += 1UL;
    } else {
        magnitude = (unsigned long)x;
    }

    do {
        result.data[result.length] = 48L + (long)(magnitude % 10UL);
        result.length++;
        magnitude /= 10UL;
    } while (magnitude != 0UL);

    left = 0;
    right = result.length - 1;
    while (left < right) {
        // doc: A temporary character used to reverse the digit sequence.
        long temporary;
        temporary = result.data[left];
        result.data[left] = result.data[right];
        result.data[right] = temporary;
        left++;
        right--;
    }

    if (x < 0) {
        // doc: An index used to shift digits right for the minus sign.
        long index;
        index = result.length;
        while (index > 0) {
            result.data[index] = result.data[index - 1];
            index--;
        }
        result.data[0] = 45L;
        result.length++;
    }

    return result;
}

// doc: int(s) for a one-character ASCII string containing '0' through '9'
// returns the corresponding integer. Any other one-character ASCII string
// raises ValueError.
py_int_result py_int_ascii_char(long character)
{
    // doc: The modeled conversion result.
    py_int_result result;
    result.ok = character >= 48L && character <= 57L;
    result.value = result.ok ? character - 48L : 0L;
    return result;
}

// doc: Sequence indexing accepts indices from zero through length-1 and
// negative indices from -length through -1. Other indices raise IndexError.
// The sequence must have a nonnegative length and valid storage for that length.
py_index_result py_index_long(const long *items, long length, long index)
{
    // doc: The modeled indexing result.
    py_index_result result;
    result.ok = 0;
    result.value = 0L;

    if (index >= 0L) {
        if (index < length) {
            result.ok = 1;
            result.value = items[index];
        }
    } else if (index >= -length) {
        result.ok = 1;
        result.value = items[length + index];
    }

    return result;
}

// doc: map(int, string) creates a lazy iterator positioned before the first
// character and performs no conversion until iteration requests an item.
py_int_char_map py_map_int_string(const py_string *source)
{
    // doc: The newly created lazy map iterator.
    py_int_char_map iterator;
    iterator.source = source;
    iterator.position = 0L;
    return iterator;
}

// doc: Requests the next value from map(int, string). It returns 1 on success,
// 0 when Python would raise StopIteration, and -1 when int() raises ValueError.
// A character is consumed before its conversion is attempted.
int py_int_char_map_next(py_int_char_map *iterator, long *value)
{
    if (iterator->position >= iterator->source->length)
        return 0;

    // doc: The conversion result for the consumed source character.
    py_int_result converted;
    converted = py_int_ascii_char(
        iterator->source->data[iterator->position]);
    iterator->position++;

    if (!converted.ok)
        return -1;

    *value = converted.value;
    return 1;
}

// doc: sum(iterable) starts with integer zero and adds values from left to
// right. For integer elements Python uses arbitrary-precision arithmetic and
// raises no value-dependent exception. This representation requires every
// intermediate mathematical sum to fit in long.
long py_sum_longs(const long *items, long length)
{
    // doc: The accumulated sum, initially Python's default start value zero.
    long total;
    // doc: The index of the next element consumed in iteration order.
    long index;
    total = 0L;
    index = 0L;
    while (index < length) {
        total += items[index];
        index++;
    }
    return total;
}

// doc: enumerate(sequence) with omitted start begins at integer zero and yields
// pairs (index, element) in the underlying sequence's iteration order.
py_enumerate_long py_enumerate_default(const long *items, long length)
{
    // doc: The newly initialized enumerate iterator.
    py_enumerate_long iterator;
    iterator.items = items;
    iterator.length = length;
    iterator.position = 0L;
    return iterator;
}

// doc: Advances enumerate(sequence). It returns 1 and writes the next index and
// element, or returns 0 when Python would raise StopIteration.
int py_enumerate_next(
    py_enumerate_long *iterator, long *index, long *element)
{
    if (iterator->position >= iterator->length)
        return 0;
    *index = iterator->position;
    *element = iterator->items[iterator->position];
    iterator->position++;
    return 1;
}

// doc: Assigning d[key] = (first, second) replaces the value when an equal
// integer key already exists without changing its insertion position.
// Otherwise it appends a new entry. capacity must be sufficient for all
// distinct keys, modeling Python's dynamically growing dictionary storage.
void py_dict_set_pair(
    py_long_pair_dict *dictionary,
    long key,
    long first,
    long second)
{
    // doc: The current dictionary insertion-order position being examined.
    long index;
    index = 0L;
    while (index < dictionary->length) {
        if (dictionary->keys[index] == key) {
            dictionary->value0[index] = first;
            dictionary->value1[index] = second;
            return;
        }
        index++;
    }

    dictionary->keys[dictionary->length] = key;
    dictionary->value0[dictionary->length] = first;
    dictionary->value1[dictionary->length] = second;
    dictionary->length++;
}

// doc: Python tuple comparison is lexicographic: the first unequal component
// determines the result, and the second component is compared only when the
// first components are equal.
int py_pair_less(long a0, long a1, long b0, long b1)
{
    return a0 < b0 || (a0 == b0 && a1 < b1);
}

// doc: sorted(dictionary.items(), key selecting an integer pair) returns keys
// ordered lexicographically by their associated pair keys. Sorting is stable,
// so equal pair keys retain dictionary insertion order. The dictionary is not
// mutated, and output must have capacity for dictionary->length keys.
void py_sorted_dict_keys_by_pair(
    const py_long_pair_dict *dictionary,
    long *output)
{
    // doc: The insertion-order position copied into the result.
    long index;
    index = 0L;
    while (index < dictionary->length) {
        output[index] = dictionary->keys[index];
        index++;
    }

    index = 1L;
    while (index < dictionary->length) {
        // doc: The key currently being inserted into the stable sorted prefix.
        long key;
        // doc: The first pair component associated with key.
        long first;
        // doc: The second pair component associated with key.
        long second;
        // doc: The current insertion position in the output.
        long position;
        // doc: A dictionary position used to locate a key's pair value.
        long lookup;

        key = output[index];
        first = 0L;
        second = 0L;
        lookup = 0L;
        while (dictionary->keys[lookup] != key)
            lookup++;
        first = dictionary->value0[lookup];
        second = dictionary->value1[lookup];

        position = index;
        while (position > 0L) {
            // doc: The dictionary position of the preceding output key.
            long previous_lookup;
            previous_lookup = 0L;
            while (dictionary->keys[previous_lookup] != output[position - 1L])
                previous_lookup++;

            if (!py_pair_less(
                    first,
                    second,
                    dictionary->value0[previous_lookup],
                    dictionary->value1[previous_lookup]))
                break;

            output[position] = output[position - 1L];
            position--;
        }
        output[position] = key;
        index++;
    }
}

