// synth: library theory (phase 0)
// doc: This capacity is sufficient for the optional minus sign and all
// decimal digits of any C long, which represents a bounded Python int.
enum { PY_LONG_STR_CAP = sizeof(long) * 3 + 2 };

// doc: A Python string has a nonnegative length and ordered Unicode characters.
// This representation is used for decimal strings produced from a C long.
typedef struct {
    // doc: The number of characters in the string.
    long length;
    // doc: Character codes in Python iteration and indexing order.
    long data[PY_LONG_STR_CAP];
} PyString;

// doc: A realized Python list of characters preserves insertion order and may
// contain duplicate elements.
typedef struct {
    // doc: The number of elements in the list.
    long length;
    // doc: Character codes in list iteration and indexing order.
    long data[PY_LONG_STR_CAP];
} PyCharList;

// doc: filter(predicate, iterable) returns a lazy iterator that tests elements
// in iterable order and yields exactly those for which predicate is true.
// This type represents filtering a string by equality with one character.
typedef struct {
    // doc: The immutable source string traversed from left to right.
    PyString source;
    // doc: The character code to which each source character is compared.
    long target;
} PyCharEqualityFilter;

// doc: Python a % b returns the remainder having the sign of b and magnitude
// less than abs(b). If b is zero, Python raises ZeroDivisionError.
typedef struct {
    // doc: This is nonzero exactly when Python raises ZeroDivisionError.
    int zero_division;
    // doc: When zero_division is zero, this is Python's remainder.
    long value;
} PyModuloResult;

// doc: Python range(stop) iterates over 0, 1, ..., stop-1 when stop is positive
// and is empty when stop is zero or negative.
typedef struct {
    // doc: The exclusive upper bound supplied to range.
    long stop;
} PyRange;

// doc: A range iteration step either produces the value at a nonnegative
// iteration position or signals exhaustion as Python iteration does.
typedef struct {
    // doc: This is nonzero exactly when an iteration value exists.
    int has_value;
    // doc: When has_value is nonzero, this is the yielded Python integer.
    long value;
} PyRangeStep;

// doc: Computes Python integer remainder. A zero divisor is represented by
// zero_division being nonzero because Python raises ZeroDivisionError then.
PyModuloResult py_int_mod(long a, long b)
{
    // doc: The modeled Python result, including exceptional completion.
    PyModuloResult result;
    if (b == 0) {
        result.zero_division = 1;
        result.value = 0;
        return result;
    }

    // doc: C's remainder, adjusted below to Python's divisor-sign convention.
    long remainder;
    remainder = a % b;
    if (remainder != 0 &&
        ((remainder < 0 && b > 0) || (remainder > 0 && b < 0))) {
        remainder += b;
    }
    result.zero_division = 0;
    result.value = remainder;
    return result;
}

// doc: str(i) for a Python integer returns its base-ten representation with no
// leading zeros; zero becomes "0", and a negative value begins with "-".
PyString py_str_long(long value)
{
    // doc: The resulting decimal string.
    PyString result;
    // doc: A value repeatedly divided toward zero to extract decimal digits.
    long remaining;
    // doc: The current output position.
    long position;
    // doc: A loop index used to reverse the initially extracted characters.
    long left;
    // doc: A loop index used to reverse the initially extracted characters.
    long right;

    remaining = value;
    position = 0;

    if (remaining == 0) {
        result.data[position++] = '0';
    } else {
        while (remaining != 0) {
            // doc: The C remainder is in -9 through 9 and is converted safely
            // to the corresponding nonnegative decimal digit.
            long digit;
            digit = remaining % 10;
            if (digit < 0)
                digit = -digit;
            result.data[position++] = '0' + digit;
            remaining /= 10;
        }
        if (value < 0)
            result.data[position++] = '-';
    }

    left = 0;
    right = position - 1;
    while (left < right) {
        // doc: A temporary character used while reversing the string.
        long temporary;
        temporary = result.data[left];
        result.data[left] = result.data[right];
        result.data[right] = temporary;
        ++left;
        --right;
    }

    result.length = position;
    return result;
}

// doc: range(stop) constructs an immutable range beginning at zero with step
// one. Construction accepts every represented Python integer stop.
PyRange py_range(long stop)
{
    // doc: The constructed range value.
    PyRange result;
    result.stop = stop;
    return result;
}

// doc: Iterating range(stop) at position k yields k when 0 <= k < stop.
// Otherwise the iterator is exhausted and Python's next operation raises
// StopIteration, represented here by has_value being zero.
PyRangeStep py_range_iteration_step(PyRange range_value, long position)
{
    // doc: The represented iteration outcome.
    PyRangeStep result;
    if (position >= 0 && position < range_value.stop) {
        result.has_value = 1;
        result.value = position;
    } else {
        result.has_value = 0;
        result.value = 0;
    }
    return result;
}

// doc: filter(lambda c: c == target, source) creates a lazy iterator. Character
