// doc: list(filter_object) exhausts the filter in source iteration order and
// creates a new list containing exactly the yielded elements, preserving order.
PyCharList py_list_from_char_equality_filter(PyCharEqualityFilter filter_value)
{
    // doc: The realized list.
    PyCharList result;
    // doc: The current source-string index.
    long index;

    result.length = 0;
    index = 0;
    while (index < filter_value.source.length) {
        if (filter_value.source.data[index] == filter_value.target) {
            result.data[result.length] = filter_value.source.data[index];
            ++result.length;
        }
        ++index;
    }
    return result;
}

