// doc: Represents the numeric values used here: either a Python integer or
// negative infinity. Python compares negative infinity as less than every
// integer.
typedef enum {
    PY_NUMBER_NEGATIVE_INFINITY,
    PY_NUMBER_INTEGER
} PyNumberKind;

// doc: Represents a Python integer or negative infinity without losing
// precision when an integer is compared with a float.
typedef struct {
    // doc: Identifies whether the value is an integer or negative infinity.
    PyNumberKind kind;
    // doc: Stores the integer value when kind is PY_NUMBER_INTEGER.
    long integer;
} PyNumber;

// doc: Returns the value produced by float("-inf"). That conversion succeeds
// exactly and produces negative infinity; malformed numeric strings would
// instead raise ValueError.
PyNumber py_float_negative_infinity(void)
{
    // doc: Holds the represented Python negative-infinity value.
    PyNumber result;
    result.kind = PY_NUMBER_NEGATIVE_INFINITY;
    result.integer = 0;
    return result;
}

// doc: Converts a represented Python integer to the corresponding numeric
// value. This conversion is exact and raises no exception.
PyNumber py_number_from_integer(long value)
{
    // doc: Holds the represented Python integer value.
    PyNumber result;
    result.kind = PY_NUMBER_INTEGER;
    result.integer = value;
    return result;
}

// doc: Implements Python's less-than comparison for the represented numeric
// values. Negative infinity is less than every integer, no integer is less
// than negative infinity, and integers are compared exactly.
int py_number_less(PyNumber left, PyNumber right)
{
    if (left.kind == PY_NUMBER_NEGATIVE_INFINITY)
        return right.kind != PY_NUMBER_NEGATIVE_INFINITY;
    if (right.kind == PY_NUMBER_NEGATIVE_INFINITY)
        return 0;
    return left.integer < right.integer;
}

// doc: Returns the number of '1' characters in bin(value). Python bin formats
// an integer's magnitude in base two with prefix "0b" and a preceding minus
// sign for negative values, so this is the population count of its magnitude.
// bin raises TypeError when its argument has no __index__ method; every
// represented long is a valid integer, so no exception occurs here.
long py_bin_count_ones(long value)
{
    // doc: Holds the nonnegative magnitude whose binary digits bin displays.
    unsigned long magnitude;
    // doc: Accumulates the number of displayed binary digits equal to '1'.
    long count;

    if (value < 0) {
        magnitude = (unsigned long)(-(value + 1));
        magnitude += 1UL;
    } else {
        magnitude = (unsigned long)value;
    }

    count = 0;
    while (magnitude != 0UL) {
        count += (long)(magnitude & 1UL);
        magnitude >>= 1;
    }
    return count;
}

// doc: Represents a Python two-element tuple whose first element is an integer
// and whose second element is a represented numeric value.
typedef struct {
    // doc: Stores the tuple's first element.
    long first;
    // doc: Stores the tuple's second element.
    PyNumber second;
} PyKeyTuple;

// doc: Implements Python lexicographic less-than comparison for these tuples.
// Python compares the first unequal corresponding elements; if the first
// elements are equal it compares the second elements. Unsupported element
// comparisons would raise TypeError, but all represented elements are
// mutually comparable.
int py_key_tuple_less(PyKeyTuple left, PyKeyTuple right)
{
    if (left.first < right.first)
        return 1;
    if (left.first > right.first)
        return 0;
    return py_number_less(left.second, right.second);
}

// doc: Represents a total Python key function from a represented integer to a
// two-element tuple. Python list.sort calls a supplied key function exactly
// once for each element; any exception from it is propagated.
typedef PyKeyTuple (*PyLongKeyFunction)(long);

// doc: Stores an element together with the key computed for it, reflecting
// Python list.sort's single key-function invocation per element.
typedef struct {
    // doc: Stores the original list element.
    long value;
    // doc: Stores the element's computed sort key.
    PyKeyTuple key;
} PyDecoratedLong;

// doc: Implements normal completion of Python list.sort(key=...) for a mutable
// list of represented integers. It sorts in place, is stable, and conceptually
// returns None. Equal keys retain their original order. The length must be
// nonnegative and items must address at least length elements. Python
// propagates exceptions raised by the key function or key comparisons; this
// restricted C interface accepts only total, non-raising operations.
void py_long_list_sort(long *items, long length, PyLongKeyFunction key_function)
{
    // doc: Caches one key per list element, as Python computes each key once.
    PyDecoratedLong decorated[(length > 0) ? length : 1];
    // doc: Indexes elements in their original or sorted order.
    long i;
    // doc: Indexes earlier elements while performing a stable insertion.
    long j;
    // doc: Temporarily holds one decorated element during stable sorting.
    PyDecoratedLong current;

    if (length <= 0)
        return;

    for (i = 0; i < length; ++i) {
        decorated[i].value = items[i];
        decorated[i].key = key_function(items[i]);
    }

    for (i = 1; i < length; ++i) {
        current = decorated[i];
        j = i;
        while (j > 0 &&
               py_key_tuple_less(current.key, decorated[j - 1].key)) {
            decorated[j] = decorated[j - 1];
            --j;
        }
        decorated[j] = current;
    }

    for (i = 0; i < length; ++i)
        items[i] = decorated[i].value;
}

