// doc: A Python string is an immutable sequence of Unicode character codes.
// len is nonnegative and at most NFV_LEN_MAX; data beyond len is irrelevant.
typedef struct {
    // doc: data stores the string's character codes in sequence order.
    long data[NFV_LEN_MAX];
    // doc: len is the number of characters in the string.
    long len;
} PyString;

// doc: A bounded sequence of Python strings. Splitting a string of length at
// most NFV_LEN_MAX can produce at most NFV_LEN_MAX + 1 components.
typedef struct {
    // doc: data stores strings in sequence order.
    PyString data[NFV_LEN_MAX + 1];
    // doc: len is the number of strings in the sequence.
    long len;
} PyStringList;

// doc: A Python dictionary from strings to integers. Entries are retained in
// insertion order; assigning an existing key does not change its position.
typedef struct {
    // doc: keys stores distinct dictionary keys in insertion order.
    PyString keys[NFV_LEN_MAX + 1];
    // doc: values stores the integer corresponding to each key.
    long values[NFV_LEN_MAX + 1];
    // doc: len is the current number of dictionary entries.
    long len;
} PyLongDict;

// doc: A materialized Python list of integers, preserving source iteration order.
typedef struct {
    // doc: data stores the list elements in order.
    long data[NFV_LEN_MAX + 1];
    // doc: len is the number of list elements.
    long len;
} PyLongList;

// doc: The result of dictionary subscription. If found is zero, Python raises
// KeyError and value has no meaning; otherwise value is the associated integer.
typedef struct {
    // doc: found is nonzero exactly when subscription succeeds.
    int found;
    // doc: value is the associated Python integer when found is nonzero.
    long value;
} PyDictLookup;

// doc: The result of max() on Python integers. max([]) raises ValueError;
// otherwise raised is zero and value is the greatest element.
typedef struct {
    // doc: raised is nonzero exactly when max() raises ValueError.
    int raised;
    // doc: value is the maximum when raised is zero.
    long value;
} PyMaxResult;

// doc: A Python dictionary-items iterator traverses entries in insertion order.
// It raises RuntimeError if the dictionary size changes during iteration.
typedef struct {
    // doc: dict is the dictionary currently being iterated.
    PyLongDict *dict;
    // doc: index is the position of the next entry.
    long index;
    // doc: expected_len is the dictionary size when iteration began.
    long expected_len;
} PyDictItemsIterator;

// doc: The result of advancing a dictionary-items iterator. RuntimeError takes
// precedence when the size changed; otherwise stopped denotes StopIteration.
typedef struct {
    // doc: runtime_error is nonzero exactly when advancing raises RuntimeError.
    int runtime_error;
    // doc: stopped is nonzero exactly when advancing raises StopIteration.
    int stopped;
    // doc: key is the next key when no exception is indicated.
    PyString key;
    // doc: value is the next value when no exception is indicated.
    long value;
} PyDictItemNext;

// doc: Python string equality is true exactly when lengths and all corresponding
// Unicode character codes are equal; it does not raise for two strings.
int py_string_equal(PyString left, PyString right)
{
