typedef long (*nfv_cmp_fn)(long, long);

// doc: Writes bin(x) to output as character codes and returns its length.
// doc: Zero becomes "0b0"; positive values have prefix "0b"; negative values
// doc: have prefix "-0b" followed by the magnitude. A valid integer raises no
// doc: exception. output must have enough writable space.
long nfv_py_bin(long x, long *output) {
    // doc: Holds the magnitude of x without overflowing for the most negative long.
    unsigned long magnitude;
    // doc: Tracks the next output position.
    long position;
    // doc: Marks the first binary digit for later reversal.
    long digit_start;
    // doc: Index used while reversing the digits.
    long left;
    // doc: Index used while reversing the digits.
    long right;
    // doc: Temporary character used during reversal.
    long temporary;

    magnitude = x < 0 ? 0UL - (unsigned long)x : (unsigned long)x;
    position = 0;

    if (x < 0)
        output[position++] = 45;
    output[position++] = 48;
    output[position++] = 98;
    digit_start = position;

    do {
        output[position++] = (long)(48UL + (magnitude & 1UL));
        magnitude >>= 1;
    } while (magnitude != 0UL);

    left = digit_start;
    right = position - 1;
    while (left < right) {
        temporary = output[left];
        output[left] = output[right];
        output[right] = temporary;
        ++left;
        --right;
    }
    return position;
}

