    // ASCII '-'; indexing these elements yields one-character strings.
    long data[NFV_PY_STR_CAP];
} nfv_py_string;

// doc: Python integer modulo by zero raises ZeroDivisionError. Otherwise
// a % b has the sign of b, satisfies a == (a // b) * b + a % b, and has
// absolute value less than abs(b).
typedef struct {
    // doc: This is nonzero exactly when Python raises ZeroDivisionError.
    int zero_division_error;
    // doc: When zero_division_error is zero, this is the Python remainder.
    long value;
} nfv_py_mod_result;

// doc: str(x) for an integer returns its base-ten representation, with no
// leading zeroes and with a leading '-' exactly when x is negative. Zero
// becomes "0". Allocation failure raises MemoryError in Python.
nfv_py_string nfv_str_long(long x)
{
    // doc: The result represents the string produced by str(x).
    nfv_py_string result;
    // doc: This unsigned magnitude equals abs(x), including for the least
    // representable signed long.
    unsigned long magnitude;
    // doc: This counts generated decimal digits.
    long digits;
    // doc: This is a loop index within the bounded representation.
    long i;
    // doc: This records whether str(x) begins with '-'.
    int negative;

    result.len = 0;
    for (i = 0; i < (long)NFV_PY_STR_CAP; ++i)
        result.data[i] = 0;

    negative = x < 0;
    magnitude = negative
        ? (unsigned long)(-(x + 1)) + 1UL
        : (unsigned long)x;

    digits = 0;
    do {
        result.data[digits] = (long)('0' + magnitude % 10UL);
        magnitude /= 10UL;
        ++digits;
    } while (magnitude != 0UL);

    for (i = 0; i < digits / 2; ++i) {
        // doc: This temporarily holds one character while reversing digits.
        long temporary;
        temporary = result.data[i];
        result.data[i] = result.data[digits - 1 - i];
        result.data[digits - 1 - i] = temporary;
    }

    if (negative) {
        for (i = digits; i > 0; --i)
            result.data[i] = result.data[i - 1];
        result.data[0] = '-';
        ++digits;
    }

    result.len = digits;
    return result;
}

