// synth: library theory (phase 0)
// doc: A Python string is an immutable sequence of character codes. Its length is
// between zero and NFV_LEN_MAX; valid indices are zero through len minus one.
typedef struct {
    // doc: data stores the character codes in sequence order.
    long data[NFV_LEN_MAX];
    // doc: len is the number of characters present.
    long len;
} py_string;

// doc: The result of str.split(' ') contains substrings in source order. Empty
// substrings are retained at boundaries and between consecutive spaces.
typedef struct {
    // doc: A length-N string can produce at most N plus one substrings.
    py_string items[NFV_LEN_MAX + 1];
    // doc: len is the number of substrings and is always at least one.
    long len;
} py_string_list;

// doc: str.split(' ') splits at every individual space character. Unlike split()
// without an argument, it does not combine runs of spaces or discard empty
// substrings. Valid string inputs cause no exception.
py_string_list py_string_split_space(py_string source) {
    // doc: result accumulates the substrings in their original order.
    py_string_list result;
    // doc: start is the index at which the current substring begins.
    long start;
    // doc: i scans characters and the virtual boundary after the final character.
    long i;
    result.len = 0;
    start = 0;
    for (i = 0; i <= source.len; ++i) {
        if (i == source.len || source.data[i] == 32) {
            // doc: piece is the substring from start up to, but not including, i.
            py_string piece;
            // doc: j scans the characters copied into piece.
            long j;
            piece.len = i - start;
            for (j = 0; j < piece.len; ++j)
                piece.data[j] = source.data[start + j];
            result.items[result.len] = piece;
            result.len++;
            start = i + 1;
        }
    }
    return result;
}

// doc: Python string equality is true exactly when lengths and all corresponding
// character codes are equal; it does not raise for two string operands.
int py_string_equal(py_string left, py_string right) {
    // doc: i scans corresponding character positions.
    long i;
    if (left.len != right.len)
        return 0;
    for (i = 0; i < left.len; ++i)
        if (left.data[i] != right.data[i])
            return 0;
    return 1;
}

// doc: A dictionary entry associates one string key with one integer value.
typedef struct {
    // doc: key is the entry's string key.
    py_string key;
    // doc: value is the integer currently associated with key.
    long value;
} py_str_long_entry;

// doc: A Python dictionary preserves key insertion order. Updating an existing
// key does not change its position; deleting and reinserting would place it last.
typedef struct {
    // doc: entries contains live entries in insertion order.
    py_str_long_entry entries[NFV_LEN_MAX + 1];
    // doc: len is the number of live entries.
    long len;
} py_str_long_dict;

// doc: An empty dictionary has no entries. Constructing it raises no exception.
py_str_long_dict py_str_long_dict_empty(void) {
    // doc: result is the newly constructed empty dictionary.
    py_str_long_dict result;
    result.len = 0;
    return result;
}

