// Dictionary membership tests keys, not values, and does not alter the dictionary.
int py_str_long_dict_contains(const py_str_long_dict *dict, py_string key) {
    // doc: i scans entries in insertion order.
    long i;
    for (i = 0; i < dict->len; ++i)
        if (py_string_equal(dict->entries[i].key, key))
            return 1;
    return 0;
}

// doc: A dictionary lookup result distinguishes a stored value from KeyError.
// Python subscription returns the value when found and raises KeyError otherwise.
typedef struct {
    // doc: found is nonzero exactly when subscription would succeed.
    int found;
    // doc: value is meaningful only when found is nonzero.
    long value;
} py_str_long_lookup;

// doc: String-key dictionary subscription returns the associated value when the
// key exists; when it does not exist, Python raises KeyError.
py_str_long_lookup py_str_long_dict_get(
    const py_str_long_dict *dict, py_string key) {
    // doc: result records either the located value or the KeyError case.
    py_str_long_lookup result;
    // doc: i scans entries in insertion order.
    long i;
    for (i = 0; i < dict->len; ++i) {
        if (py_string_equal(dict->entries[i].key, key)) {
            result.found = 1;
            result.value = dict->entries[i].value;
            return result;
        }
    }
    result.found = 0;
    result.value = 0;
    return result;
