// changing insertion order. For a new key it appends an entry at the end. This
// bounded representation requires room for every distinct key assigned.
void py_str_long_dict_set(
    py_str_long_dict *dict, py_string key, long value) {
    // doc: i scans existing entries in insertion order.
    long i;
    for (i = 0; i < dict->len; ++i) {
