// doc: Represents the result of indexing a Python list of integers. If
// raised_index_error is nonzero, Python raises IndexError and value is irrelevant.
typedef struct {
    // doc: Nonzero exactly when the index is outside [-length, length-1].
    int raised_index_error;
    // doc: The indexed element when raised_index_error is zero.
    long value;
} nfv_py_list_index_result;

// doc: Returns the result of Python list indexing. Negative indices count from
// the end. An index outside [-length, length-1] raises IndexError. The caller
// must provide a nonnegative length and an array containing at least length items.
nfv_py_list_index_result nfv_py_list_index_long(
    const long *items, long length, long index)
{
    // doc: Stores the indexing result, including whether IndexError is raised.
    nfv_py_list_index_result result;

    if (index < 0) {
        if (index < -length) {
            result.raised_index_error = 1;
            result.value = 0;
            return result;
        }
        index += length;
    }

    if (index >= length) {
        result.raised_index_error = 1;
        result.value = 0;
        return result;
    }

    result.raised_index_error = 0;
    result.value = items[index];
    return result;
}

// doc: Represents one step of iteration over a Python list of integers.
// has_value is nonzero when value is the next element; otherwise iteration has
// ended and Python's iterator protocol raises StopIteration.
