// length it represents StopIteration. The caller must provide a nonnegative
// length, a nonnegative position, and an array containing at least length items.
nfv_py_list_iteration_result nfv_py_list_iter_long(
    const long *items, long length, long position)
{
    // doc: Stores either the next element or the end-of-iteration indication.
    nfv_py_list_iteration_result result;

    if (position >= length) {
        result.has_value = 0;
        result.value = 0;
        return result;
    }

    result.has_value = 1;
    result.value = items[position];
    return result;
}

