// doc: A represented Python string is an immutable sequence of Unicode code
// doc: points. Its length is between zero and NFV_LEN_MAX + 10 inclusive.
typedef struct {
    // doc: These are the Unicode code points in sequence order.
    long data[NFV_LEN_MAX + 10];
    // doc: Python len() reports this number of code points.
    long len;
} nfv_py_string;

// doc: A represented Python list stores strings in insertion order. Its length
// doc: is between zero and NFV_LEN_MAX + 1 inclusive.
typedef struct {
    // doc: These are the list elements in iteration and indexing order.
    nfv_py_string data[NFV_LEN_MAX + 1];
    // doc: Python len() reports this number of elements.
    long len;
} nfv_py_string_list;

// doc: This represents a string produced by joining at most NFV_LEN_MAX + 1
// doc: represented strings. Python strings are sequences of Unicode code points.
typedef struct {
    // doc: These are the resulting Unicode code points in sequence order.
    long data[(2 * NFV_LEN_MAX + 1) * (NFV_LEN_MAX + 10)];
    // doc: Python len() reports this number of code points.
    long len;
} nfv_py_joined_string;

// doc: str.isspace() is true exactly when the one-character string is Unicode
// doc: whitespace: category Zs or bidirectional class WS, B, or S. It is false
// doc: otherwise and raises no exception for a string receiver.
int nfv_py_isspace(long c)
{
    return (c >= 0x0009 && c <= 0x000d) ||
           (c >= 0x001c && c <= 0x0020) ||
           c == 0x0085 || c == 0x00a0 || c == 0x1680 ||
           (c >= 0x2000 && c <= 0x200a) ||
           c == 0x2028 || c == 0x2029 || c == 0x202f ||
           c == 0x205f || c == 0x3000;
}

