// doc: raises TypeError for an object without a length and OverflowError if the
// doc: reported length exceeds sys.maxsize; neither occurs for this bounded type.
long nfv_py_str_len(const nfv_py_string *s)
{
    return s->len;
}

// doc: len(xs) returns the number of elements in a list. Python raises TypeError
// doc: for an object without a length and OverflowError if the reported length
// doc: exceeds sys.maxsize; neither occurs for this bounded type.
long nfv_py_list_len(const nfv_py_string_list *xs)
{
    return xs->len;
}

// doc: s.split() with no separator treats each maximal run of Unicode whitespace
// doc: as one separator and omits leading, trailing, and empty fields. An empty
// doc: or all-whitespace string produces an empty list. Results preserve order.
// doc: Python may raise MemoryError if allocation fails.
nfv_py_string_list nfv_py_split_whitespace(const nfv_py_string *s)
{
    // doc: This is the resulting ordered list of fields.
    nfv_py_string_list out;
    // doc: This indexes code points and result slots.
    long i;
    // doc: This indexes storage while initializing it.
    long j;
    // doc: This is the inclusive start of the current non-whitespace field.
    long start;

    out.len = 0;
    for (i = 0; i < NFV_LEN_MAX + 1; i++) {
        out.data[i].len = 0;
        for (j = 0; j < NFV_LEN_MAX + 10; j++)
            out.data[i].data[j] = 0;
    }

    if (s->len < 0 || s->len > NFV_LEN_MAX)
        return out;

    i = 0;
    while (i < s->len) {
        while (i < s->len && nfv_py_isspace(s->data[i]))
            i++;
        if (i == s->len)
