        start = i;
        while (i < s->len && !nfv_py_isspace(s->data[i]))
            i++;

        out.data[out.len].len = i - start;
        for (j = start; j < i; j++)
            out.data[out.len].data[j - start] = s->data[j];
        out.len++;
    }
    return out;
}

