    long length;
} py_string;

// doc: String equality compares lengths and then corresponding Unicode code
// points. Empty strings compare equal. It raises no exception.
int py_string_equal(py_string left, py_string right)
{
    long i;
    if (left.length != right.length)
        return 0;
    for (i = 0; i < left.length; ++i)
        if (left.codepoints[i] != right.codepoints[i])
            return 0;
    return 1;
}

// doc: str.isupper() returns true exactly when the string contains at least one
// cased Unicode character and every cased character is uppercase. Uncased
// characters are ignored. The one-character strings used during string
// iteration therefore return true exactly for uppercase cased code points.
// Calling this method on a non-string raises AttributeError.
int py_string_isupper(py_string value);

// doc: A dictionary item consists of a key and its associated value.
typedef struct {
    py_string key;
    long value;
} py_dict_item;

// doc: Dictionary assignment compares string keys by value. An equal existing
// key has its value replaced without changing its insertion position; a new key
// is appended at the end. Python may raise MemoryError if growth fails. This
// bounded representation instead requires capacity for every distinct key.
void py_dict_set(py_dict_item *items, long *length, long capacity,
                 py_string key, long value)
{
    long i;
    for (i = 0; i < *length; ++i) {
        if (py_string_equal(items[i].key, key)) {
            items[i].value = value;
            return;
        }
    }
    if (*length < capacity) {
        items[*length].key = key;
        items[*length].value = value;
        ++*length;
    }
}

// doc: The result of list.index records either the zero-based index of the
// first equal element or that Python raised ValueError because no element was
// equal.
typedef struct {
    long index;
    int value_error;
} py_index_result;

