// and returns the first matching index. It raises ValueError if no element
// matches.
py_index_result py_string_list_index(const py_string *items, long length,
                                     py_string value)
{
    long i;
    py_index_result result;
    for (i = 0; i < length; ++i) {
        if (py_string_equal(items[i], value)) {
            result.index = i;
            result.value_error = 0;
            return result;
        }
    }
    result.index = 0;
    result.value_error = 1;
    return result;
}

// doc: A decorated value represents an item and the two integer components of
