// requires the destination to have room for count items.
void py_sorted_keyed_items(const py_keyed_item *source,
                           py_keyed_item *destination, long count)
{
    long i;
    long j;
    py_keyed_item current;

    for (i = 0; i < count; ++i)
        destination[i] = source[i];

    for (i = 1; i < count; ++i) {
        current = destination[i];
        j = i;
        while (j > 0 &&
