// synth: library theory (phase 0)
// doc: A bounded Python sequence stores elements in iteration order. Its length is between zero and NFV_LEN_MAX inclusive.
typedef struct {
    long items[NFV_LEN_MAX];
    long length;
} nfv_sequence;

// doc: An indexed access either yields the selected element or reports IndexError. Negative indices count from the end; indices outside [-length, length-1] raise IndexError.
typedef struct {
    long value;
    int index_error;
} nfv_index_result;

// doc: Conversion of a one-character string containing an ASCII decimal digit yields that digit's value. Any other one-character string raises ValueError.
typedef struct {
    long value;
    int value_error;
} nfv_digit_result;

// doc: Converting a Python integer to str produces its base-ten ASCII representation with no leading zeroes, except that zero becomes "0"; negative values begin with '-'. It raises no value-related exception.
nfv_sequence nfv_str_long(long value)
{
    nfv_sequence result;
    unsigned long magnitude;
    long reverse_digits[NFV_LEN_MAX];
    long count = 0;
    long out = 0;

    result.length = 0;

    if (value < 0)
        magnitude = 0UL - (unsigned long)value;
    else
        magnitude = (unsigned long)value;

    do {
        reverse_digits[count++] = 48 + (long)(magnitude % 10UL);
        magnitude /= 10UL;
    } while (magnitude != 0UL);

    if (value < 0)
        result.items[out++] = 45;

    while (count > 0)
        result.items[out++] = reverse_digits[--count];

    result.length = out;
    return result;
}

// doc: list(string) creates a new list containing the string's characters from left to right. Mutating the new list does not mutate the string.
nfv_sequence nfv_list_from_string(nfv_sequence string_value)
{
    nfv_sequence result;
    long i;

    result.length = string_value.length;
    for (i = 0; i < string_value.length; ++i)
        result.items[i] = string_value.items[i];
    return result;
}

// doc: Sequence indexing accepts negative indices by adding the sequence length. It raises IndexError when the normalized index is outside the sequence.
nfv_index_result nfv_getitem(nfv_sequence sequence, long index)
{
    nfv_index_result result;
    long normalized = index;

    if (normalized < 0)
        normalized += sequence.length;

    result.index_error =
        normalized < 0 || normalized >= sequence.length;
    result.value = result.index_error ? 0 : sequence.items[normalized];
    return result;
}

// doc: A slice [start:] clamps start into [0, length] after adding length to a negative start, then copies elements in their original order. Such a slice never raises IndexError.
nfv_sequence nfv_slice_from(nfv_sequence sequence, long start)
{
    nfv_sequence result;
    long normalized = start;
    long i;

    if (normalized < 0) {
        normalized += sequence.length;
        if (normalized < 0)
            normalized = 0;
    }
    if (normalized > sequence.length)
        normalized = sequence.length;

    result.length = sequence.length - normalized;
    for (i = 0; i < result.length; ++i)
        result.items[i] = sequence.items[normalized + i];
    return result;
}

// doc: int applied to a one-character ASCII decimal string returns the corresponding integer. Other one-character strings raise ValueError.
nfv_digit_result nfv_int_from_digit_char(long character)
{
    nfv_digit_result result;

    result.value_error = character < 48 || character > 57;
    result.value = result.value_error ? 0 : character - 48;
    return result;
}

// doc: List item assignment normalizes a negative index by adding the list length. It replaces exactly one element, or raises IndexError and leaves the list unchanged when the index is out of range.
int nfv_setitem(nfv_sequence *sequence, long index, long value)
{
    long normalized = index;

    if (normalized < 0)
        normalized += sequence->length;
    if (normalized < 0 || normalized >= sequence->length)
        return 0;

    sequence->items[normalized] = value;
    return 1;
}

// doc: sum(sequence) starts with integer zero and adds elements from left to right. For Python integers the mathematical result is exact and no overflow occurs.
long nfv_sum(nfv_sequence sequence)
{
    long result = 0;
    long i;

    for (i = 0; i < sequence.length; ++i)
        result += sequence.items[i];
    return result;
}

// doc: A key function supplied to sorted is called exactly once for each element and returns the integer comparison key for that element.
typedef long (*nfv_key_function)(long);

// doc: sorted(sequence, key=key_function) returns a new list ordered by ascending integer keys. Sorting is stable, so elements with equal keys retain their original relative order; the input list is not mutated.
nfv_sequence nfv_sorted_by_key(nfv_sequence sequence,
                               nfv_key_function key_function)
{
    nfv_sequence result = sequence;
    long keys[NFV_LEN_MAX];
    long i;

    for (i = 0; i < sequence.length; ++i)
        keys[i] = key_function(sequence.items[i]);

    for (i = 1; i < result.length; ++i) {
        long item = result.items[i];
        long key = keys[i];
        long j = i;

        while (j > 0 && keys[j - 1] > key) {
            result.items[j] = result.items[j - 1];
            keys[j] = keys[j - 1];
            --j;
        }
        result.items[j] = item;
        keys[j] = key;
    }
    return result;
}

