        guess = 1.0e128;
    else if (value > 1.0e128)
        guess = 1.0e64;
    else if (value > 1.0e64)
        guess = 1.0e32;
    else if (value > 1.0e32)
        guess = 1.0e16;
    else if (value > 1.0e16)
        guess = 1.0e8;
    else if (value > 1.0e8)
        guess = 1.0e4;
    else if (value > 1.0e4)
        guess = 1.0e2;
    else if (value >= 1.0)
        guess = 1.0;
    else if (value < 1.0e-256)
        guess = 1.0e-128;
    else if (value < 1.0e-128)
        guess = 1.0e-64;
    else if (value < 1.0e-64)
        guess = 1.0e-32;
    else if (value < 1.0e-32)
        guess = 1.0e-16;
    else if (value < 1.0e-16)
        guess = 1.0e-8;
    else if (value < 1.0e-8)
        guess = 1.0e-4;
    else if (value < 1.0e-4)
        guess = 1.0e-2;
    else
        guess = 1.0;

    for (int i = 0; i < 220; ++i) {
        double next = (guess + value / guess) * 0.5;
        if (next == guess)
