// It returns a float rounded to the nearest decimal multiple, with exact ties
// rounded toward the choice having an even final digit. Large positive ndigits
// may leave the value unchanged; large negative ndigits may produce signed
// zero. NaN and infinities remain unchanged when ndigits is supplied.
// Unsupported argument types raise TypeError.
double py_round_ndigits(double number, long ndigits) {
    double scale;

    if (!(number == number))
        return number;
    if (number > 1.0e15 || number < -1.0e15)
        return number;

    if (ndigits == 3L)
        scale = 1000.0;
    else if (ndigits == 2L)
        scale = 100.0;
    else
        return number;

    double magnitude = number < 0.0 ? -number : number;
    double scaled = magnitude * scale;
    long long lower_integer = (long long)scaled;
    double lower = (double)lower_integer;
    double fraction = scaled - lower;
    double rounded = lower;

    if (fraction > 0.5) {
        rounded = lower + 1.0;
    } else if (fraction == 0.5) {
        if ((lower_integer % 2LL) != 0LL)
            rounded = lower + 1.0;
    }

    rounded /= scale;
    return number < 0.0 ? -rounded : rounded;
}

