// doc: Represents a Python range iterator with the implicit positive step 1.
// doc: Values are produced in ascending order from current up to, but excluding, stop.
typedef struct {
    // doc: Holds the next value to be produced.
    long current;
    // doc: Holds the excluded upper bound.
    long stop;
} py_range1_iterator;

// doc: Represents one call to next on a Python range iterator.
// doc: has_value is zero exactly when Python raises StopIteration.
typedef struct {
    // doc: Indicates whether next produced a value rather than raising StopIteration.
    int has_value;
    // doc: Holds the produced value when has_value is nonzero.
    long value;
} py_range_next_result;

// doc: Computes Python integer remainder for divisor 2.
// doc: The result is always 0 or 1, including for negative dividends; division by zero is impossible here.
long py_mod_2(long value)
{
    // doc: Holds C's remainder before adjustment to Python's nonnegative remainder.
    long remainder = value % 2;
    return remainder < 0 ? remainder + 2 : remainder;
}

// doc: Computes Python true division of an integer by 2.
// doc: It returns a float; division by zero is impossible. For C-representable Python integers, conversion and division use IEEE-style rounding to double.
double py_true_div_2(long value)
{
    return (double)value / 2.0;
}

