// doc: Nonnegative indices must be less than length. Negative indices count from the end, with -length denoting the first element.
// doc: Any index outside [-length, length-1] raises IndexError.
py_index_result py_list_index(long length, long index)
{
    // doc: Holds the indexing result and whether IndexError occurred.
    py_index_result result;

    if (index >= 0) {
        result.ok = index < length;
        result.position = result.ok ? index : 0;
    } else {
        result.ok = index >= -length;
        result.position = result.ok ? length + index : 0;
    }
    return result;
}

// doc: Creates the iterator used by Python range(start, stop), whose implicit step is 1.
// doc: The range is empty when start is greater than or equal to stop.
py_range1_iterator py_range1(long start, long stop)
{
