    py_range1_iterator iterator;
    iterator.current = start;
    iterator.stop = stop;
    return iterator;
}

// doc: Performs Python next on a step-1 range iterator.
// doc: It returns current and advances by one when current is less than stop.
// doc: Otherwise it leaves the iterator exhausted and reports the StopIteration exception.
py_range_next_result py_range1_next(py_range1_iterator *iterator)
{
    // doc: Holds either the next range value or the encoded StopIteration result.
    py_range_next_result result;

    if (iterator->current < iterator->stop) {
        result.has_value = 1;
        result.value = iterator->current;
        iterator->current++;
    } else {
        result.has_value = 0;
        result.value = 0;
    }
    return result;
}

