// synth: library theory (phase 0)
// doc: A Python list of strings is an ordered, mutable sequence. Each string
// stores its character codes and length explicitly; len is between zero and
// NFV_LEN_MAX.
typedef struct {
    long items[NFV_LEN_MAX][NFV_LEN_MAX];
    long item_lens[NFV_LEN_MAX];
    long len;
} nfv_string_list;

// doc: A Python tuple of strings is an ordered, immutable sequence. Each string
// stores its character codes and length explicitly; len is between zero and
// NFV_LEN_MAX.
typedef struct {
    long items[NFV_LEN_MAX][NFV_LEN_MAX];
    long item_lens[NFV_LEN_MAX];
    long len;
} nfv_string_tuple;

// doc: list.index(x) returns the zero-based position of the first element equal
// to x, testing from left to right. If no element is equal, Python raises
// ValueError; value_error is one exactly in that case.
typedef struct {
    long value;
    int value_error;
} nfv_index_result;

// doc: Python strings compare equal exactly when they have equal lengths and
// equal character codes at every position. String equality raises no exception.
int nfv_string_equal(const long *a, long a_len,
                     const long *b, long b_len)
{
    long i;
    if (a_len != b_len)
        return 0;
    for (i = 0; i < a_len; ++i)
        if (a[i] != b[i])
            return 0;
    return 1;
}

// doc: For a list of strings, x in list tests elements from left to right and
// returns true when the first string equal to x is found, otherwise false.
// String comparisons raise no exception.
int nfv_string_list_contains(const nfv_string_list *list,
                             const long *x, long x_len)
{
    long i;
    for (i = 0; i < list->len; ++i)
        if (nfv_string_equal(list->items[i], list->item_lens[i], x, x_len))
            return 1;
    return 0;
}

// doc: list.index(x) tests elements from left to right and returns the index of
// the first string equal to x. If none is equal, Python raises ValueError,
// represented here by value_error equal to one.
nfv_index_result nfv_string_list_index(const nfv_string_list *list,
                                       const long *x, long x_len)
{
    nfv_index_result result;
    long i;
    for (i = 0; i < list->len; ++i) {
        if (nfv_string_equal(list->items[i], list->item_lens[i], x, x_len)) {
            result.value = i;
            result.value_error = 0;
            return result;
        }
    }
    result.value = 0;
    result.value_error = 1;
    return result;
}

// doc: list[start:stop] with the default positive step returns a new list in
// the original order. Negative bounds count from the end, and either bound is
// clipped to the interval from zero through the list length. If the normalized
// stop is not greater than the normalized start, the result is empty.
nfv_string_list nfv_string_list_slice(const nfv_string_list *list,
                                      long start, long stop)
{
    nfv_string_list result;
    long first;
    long last;
    long i;
    long j;

    if (start < -list->len)
        first = 0;
    else if (start < 0)
        first = list->len + start;
    else if (start > list->len)
        first = list->len;
    else
        first = start;

    if (stop < -list->len)
        last = 0;
    else if (stop < 0)
        last = list->len + stop;
    else if (stop > list->len)
        last = list->len;
    else
        last = stop;

    result.len = 0;
    for (i = first; i < last; ++i) {
        result.item_lens[result.len] = list->item_lens[i];
        for (j = 0; j < list->item_lens[i]; ++j)
            result.items[result.len][j] = list->items[i][j];
        ++result.len;
    }
    return result;
}

// doc: tuple() returns the unique empty tuple and raises no exception.
nfv_string_tuple nfv_empty_string_tuple(void)
{
    nfv_string_tuple result;
