nfv_string_tuple nfv_string_tuple_from_list(const nfv_string_list *list)
{
    nfv_string_tuple result;
    long i;
    long j;

    result.len = list->len;
    for (i = 0; i < list->len; ++i) {
        result.item_lens[i] = list->item_lens[i];
        for (j = 0; j < list->item_lens[i]; ++j)
            result.items[i][j] = list->items[i][j];
    }
    return result;
}

