// doc: A bounded representation of a Python list of integers. Python lists
// doc: preserve element order and have a nonnegative length.
typedef struct {
    // doc: The elements in Python list order; only indices below length are valid.
    long elements[NFV_LEN_MAX];
    // doc: The number of elements, from zero through NFV_LEN_MAX in this model.
    long length;
} nfv_long_list;

// doc: len(list) returns the number of elements. Python raises OverflowError
// doc: only if the length exceeds sys.maxsize, which this bounded model excludes.
static long nfv_list_len(nfv_long_list list)
{
    return list.length;
}

// doc: list[index] returns the element at index. Negative indices count from
// doc: the end. Python raises IndexError if the adjusted index is out of range.
static long nfv_list_get(nfv_long_list list, long index)
{
    if (index < 0)
        index += list.length;
    __CPROVER_assert(index >= 0 && index < list.length,
                     "Python IndexError: list index out of range");
    return list.elements[index];
}

// doc: list.append(value) adds value at the end, mutates the list, and returns
// doc: None. Python may raise MemoryError if storage allocation fails. This
// doc: bounded representation asserts if another element cannot be represented.
static void nfv_list_append(nfv_long_list *list, long value)
{
    __CPROVER_assert(list->length < NFV_LEN_MAX,
                     "bounded list capacity exceeded");
    list->elements[list->length] = value;
    list->length += 1;
}

// doc: sorted(list) returns a new list containing the same elements in stable
// doc: ascending order and does not mutate the input. Python raises TypeError
// doc: when elements cannot be ordered and propagates exceptions from comparison;
// doc: integer elements are always orderable.
static nfv_long_list nfv_sorted(nfv_long_list input)
{
    // doc: The newly allocated logical Python list returned by sorted.
    nfv_long_list output = input;
    // doc: The insertion-sort position, ranging over valid list positions.
    long i = 1;

    while (i < output.length) {
        // doc: The element currently being inserted into the sorted prefix.
        long key = output.elements[i];
        // doc: The position immediately after the candidate predecessor.
        long j = i;

        while (j > 0 && key < output.elements[j - 1]) {
            output.elements[j] = output.elements[j - 1];
            j -= 1;
        }
        output.elements[j] = key;
        i += 1;
    }
    return output;
}

