// synth: library theory (phase 0)
// doc: Python str.isspace() is true when the string is nonempty and every
// character is Unicode whitespace. This helper models that predicate for one
// Unicode code point and raises no exception.
int nfv_py_char_isspace(long c) {
    return (c >= 0x09 && c <= 0x0d) ||
           (c >= 0x1c && c <= 0x20) ||
           c == 0x85 || c == 0xa0 || c == 0x1680 ||
           (c >= 0x2000 && c <= 0x200a) ||
           c == 0x2028 || c == 0x2029 || c == 0x202f ||
           c == 0x205f || c == 0x3000;
}

// doc: Equality between two Python strings compares their lengths and then
// corresponding Unicode code points. It raises no exception for valid strings.
int nfv_py_str_equal(const long *a, long a_len,
                     const long *b, long b_len) {
    long i;
    if (a_len < 0 || b_len < 0 || a_len != b_len)
        return 0;
    for (i = 0; i < a_len; ++i)
        if (a[i] != b[i])
            return 0;
    return 1;
}

// doc: str.split() with no separator splits at maximal runs of Unicode
// whitespace, discards leading and trailing whitespace, and never produces
// empty fields. An empty or all-whitespace string produces an empty list.
// Python may raise MemoryError while allocating the result. This bounded
// adapter stores each field as a start and length; it returns -1 if the C
// buffers are too small or the supplied representation is invalid.
long nfv_py_str_split(const long *s, long s_len,
                      long *starts, long *lengths, long max_parts) {
    long i;
    long count;
    long start;

    if (s_len < 0 || max_parts < 0)
        return -1;

    i = 0;
    count = 0;
    while (i < s_len) {
        while (i < s_len && nfv_py_char_isspace(s[i]))
            ++i;
        if (i == s_len)
            break;

        start = i;
        while (i < s_len && !nfv_py_char_isspace(s[i]))
            ++i;

        if (count >= max_parts)
            return -1;
        starts[count] = start;
        lengths[count] = i - start;
        ++count;
    }
    return count;
}

// doc: sorted() applied to a list of Python integers returns a new list in
// nondecreasing numeric order and leaves the input unchanged. Sorting is
// stable. Integer comparisons raise no exception; allocation may raise
// MemoryError. This adapter returns -1 for an invalid length or insufficient
// output capacity and otherwise returns the result length.
long nfv_py_sorted_longs(const long *input, long length,
                         long *output, long capacity) {
    long i;
    long j;
    long value;

    if (length < 0 || capacity < length)
        return -1;

    for (i = 0; i < length; ++i)
        output[i] = input[i];

    for (i = 1; i < length; ++i) {
        value = output[i];
        j = i;
        while (j > 0 && output[j - 1] > value) {
            output[j] = output[j - 1];
            --j;
        }
        output[j] = value;
    }
    return length;
}

