    long length;
} nfv_py_str_long_dict;

// doc: Indexing a Python dictionary with a string returns the value associated
// with the equal key and raises KeyError if no such key exists. String hashing
// and equality raise no exception. This adapter returns one when found and
// zero to signal the KeyError case.
int nfv_py_dict_get(const nfv_py_str_long_dict *dict,
                    const long *key, long key_len, long *value) {
    long i;
    if (dict->length < 0 || key_len < 0)
        return 0;
    for (i = 0; i < dict->length; ++i) {
