int nfv_py_dict_items_next(const nfv_py_str_long_dict *dict, long index,
                           const long **key, long *key_len, long *value) {
    if (index < 0 || index >= dict->length)
        return 0;
    *key = dict->keys[index];
    *key_len = dict->key_lengths[index];
