// result. This typed adapter excludes non-string items and returns -1 for an
// invalid representation or insufficient output capacity.
long nfv_py_str_join(const long *separator, long separator_len,
                     const long *const *items, const long *item_lengths,
                     long count, long *output, long capacity) {
    long i;
    long j;
    long used;

    if (separator_len < 0 || count < 0 || capacity < 0)
        return -1;

    used = 0;
    for (i = 0; i < count; ++i) {
        if (item_lengths[i] < 0)
            return -1;

        if (i != 0) {
            for (j = 0; j < separator_len; ++j) {
                if (used >= capacity)
                    return -1;
                output[used++] = separator[j];
            }
        }

        for (j = 0; j < item_lengths[i]; ++j) {
            if (used >= capacity)
                return -1;
            output[used++] = items[i][j];
        }
    }
    return used;
}

