// synth: library theory (phase 0)
// doc: Represents a Python string as character codes and a length. The array
// doc: capacity is sufficient for the decimal representation of any C long.
typedef struct {
    // doc: Contains the string's character codes in left-to-right order.
    long data[sizeof(long) * 3 + 3];
    // doc: Gives the number of characters stored in data.
    unsigned long length;
} py_string;

// doc: Represents one step of iterating over a two-argument Python range.
// doc: A false has_value corresponds to the iterator raising StopIteration.
typedef struct {
    // doc: Is true exactly when iteration produces a value at this position.
    int has_value;
    // doc: Is the produced integer when has_value is true; otherwise it is zero.
    long value;
} py_range_item;

// doc: Returns the item at zero-based iteration position index in range(start,
// doc: stop). Python produces start, start+1, and so on while values are less
// doc: than stop. If stop is at most start, the range is empty. Requesting a
// doc: position after the final item corresponds to StopIteration.
py_range_item py_range2_iter_item(long start, long stop, unsigned long index)
{
    // doc: Holds the encoded iterator result.
    py_range_item result;
    // doc: Holds the number of values produced by the range.
    unsigned long length;
    // doc: Holds the unsigned magnitude of a negative start value.
    unsigned long magnitude;

    result.has_value = 0;
    result.value = 0;

    if (stop <= start)
        return result;

    length = (unsigned long)stop - (unsigned long)start;
    if (index >= length)
        return result;

    result.has_value = 1;
    if (start >= 0) {
        result.value = start + (long)index;
        return result;
    }

    magnitude = (unsigned long)(-(start + 1));
    magnitude += 1;

    if (index < magnitude)
        result.value = start + (long)index;
    else if (index == magnitude)
        result.value = 0;
    else
        result.value = (long)(index - magnitude);

    return result;
}

// doc: Implements Python str(value) for an integer. It returns ASCII decimal
// doc: digits with no leading zeroes, except that zero becomes "0". Negative
// doc: values begin with '-', and positive values have no sign. Conversion of
// doc: an integer to str does not raise an exception.
py_string py_str_long(long value)
{
    // doc: Holds the resulting Python string representation.
    py_string result;
    // doc: Holds the nonnegative magnitude without overflowing on the minimum long.
    unsigned long magnitude;
    // doc: Marks where decimal digits begin after an optional minus sign.
    unsigned long digit_start;
    // doc: Is a traversal index used while reversing generated digits.
    unsigned long left;
    // doc: Is a traversal index used while reversing generated digits.
    unsigned long right;
    // doc: Temporarily stores one character code during a swap.
    long temporary;

    result.length = 0;

    if (value < 0) {
        result.data[result.length++] = '-';
        magnitude = (unsigned long)(-(value + 1));
        magnitude += 1;
    } else {
        magnitude = (unsigned long)value;
    }

    digit_start = result.length;
    do {
        result.data[result.length++] = '0' + (long)(magnitude % 10);
        magnitude /= 10;
    } while (magnitude != 0);

    left = digit_start;
    right = result.length - 1;
    while (left < right) {
        temporary = result.data[left];
        result.data[left] = result.data[right];
        result.data[right] = temporary;
        ++left;
        --right;
    }

    return result;
}

// doc: Implements s[::-1] for a Python string s. It returns every character in
// doc: reverse order; an empty or one-character string is unchanged. The fixed
// doc: step is -1, so no zero-step ValueError or indexing exception can occur.
py_string py_string_reverse(py_string value)
{
    // doc: Holds the reversed string.
    py_string result;
    // doc: Traverses valid character positions in the result.
    unsigned long index;

    result.length = value.length;
    for (index = 0; index < value.length; ++index)
        result.data[index] = value.data[value.length - index - 1];

    return result;
}

// doc: Implements equality between two Python strings. It returns true exactly
// doc: when their lengths and corresponding character codes are equal.
// doc: Comparing two strings for equality does not raise an exception.
int py_string_equal(py_string left, py_string right)
{
    // doc: Traverses corresponding valid character positions.
    unsigned long index;

    if (left.length != right.length)
        return 0;

    for (index = 0; index < left.length; ++index)
        if (left.data[index] != right.data[index])
            return 0;

    return 1;
}

